133-### NT-01 · Autoría de los documentos de F0
134-El enunciado asigna al candidato la autoría de SPEC, AGENTS, FABRICA, escenarios e INTERVENCIONES. En esta fase, **los borradores los redactó Claude Code (Opus 5.5)** por encargo explícito del humano (INT-002), a partir de su análisis del material. Consecuencias:
# TutorFlow — variables de entorno (copiar a .env; .env está en .gitignore)
# NO pongas valores reales en este archivo: el repositorio es público. Referencia: SPEC.md §11.

# --- LLM (los 400 y los 403 de identidad/referencia funcionan sin llave; las preguntas que llegan al LLM → 503) ---
LLM_API_KEY=
# anthropic | openai-compatible   (no se deduce del formato de la llave)
LLM_PROVIDER=anthropic
LLM_MODEL=claude-haiku-5-5
# Solo para openai-compatible (OpenAI, Ollama, LM Studio...), p. ej. http://host.docker.internal:11434/v1
LLM_BASE_URL=
# Precios USD por millón de tokens, para costoUsd. Verificar en la página oficial del proveedor y anotar la fecha.
LLM_PRICE_INPUT_PER_MTOK=
LLM_PRICE_OUTPUT_PER_MTOK=
LLM_MAX_TOKENS_PER_REQUEST=8000

# --- Recuperación: full-context | bm25 (vector | hybrid solo con embeddings configurados; experimento) ---
RETRIEVAL_STRATEGY=

# --- Embeddings (opcionales; solo para vector/hybrid) ---
EMBEDDING_PROVIDER=
EMBEDDING_MODEL=
EMBEDDING_API_KEY=
EMBEDDING_PRICE_PER_MTOK=

# --- Integración (los valores por defecto sirven para docker compose) ---
MOCK_API_BASE_URL=http://mock-api:4000
ROSTER_TTL_SECONDS=300
KNOWLEDGE_PATH=/app/knowledge
QUARANTINE_CHUNKS=bienestar_y_becas.md#Anexo
# Archivo de auditoría opcional (la auditoría principal va siempre a stdout)
AUDIT_LOG_PATH=
// API simulada de TutorFlow · Q10 (prueba técnica)
// Requiere Node 18+ y no tiene dependencias:  node server.js   (puerto 4000, o PORT=xxxx)
// IMPORTANTE: esta API NO valida permisos. Controlar quién puede ver qué es responsabilidad de tu aplicación.

const http = require("http");
const fs = require("fs");
const path = require("path");

const datos = JSON.parse(fs.readFileSync(path.join(__dirname, "datos.json"), "utf8"));
const PORT = process.env.PORT || 4000;

function send(res, status, body) {
  res.writeHead(status, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(body, null, 2));
}

const routes = [
  [/^\/estudiantes\/([^/]+)$/, (id) => datos.estudiantes.find((e) => e.id === id)],
  [/^\/estudiantes\/([^/]+)\/notas$/, (id) =>
    datos.estudiantes.some((e) => e.id === id) ? datos.notas.filter((n) => n.estudianteId === id) : undefined],
  [/^\/estudiantes\/([^/]+)\/asistencia$/, (id) =>
    datos.estudiantes.some((e) => e.id === id) ? datos.asistencia.filter((a) => a.estudianteId === id) : undefined],
  [/^\/programas\/([^/]+)\/estudiantes$/, (id) =>
    datos.programas.some((p) => p.id === id) ? datos.estudiantes.filter((e) => e.programaId === id) : undefined],
  [/^\/coordinadores\/([^/]+)$/, (id) => datos.coordinadores.find((c) => c.id === id)],
  [/^\/programas$/, () => datos.programas],
];

http.createServer((req, res) => {
  const url = new URL(req.url, `http://localhost:${PORT}`);
  if (req.method !== "GET") return send(res, 405, { error: "Solo GET" });
  if (url.pathname === "/salud") return send(res, 200, { estado: "ok", periodo: datos.periodo });
  for (const [re, fn] of routes) {
    const m = url.pathname.match(re);
    if (m) {
      const out = fn(decodeURIComponent(m[1] || ""));
      return out === undefined ? send(res, 404, { error: "No encontrado" }) : send(res, 200, out);
    }
  }
  send(res, 404, { error: "Ruta no existe" });
}).listen(PORT, () => console.log(`API simulada TutorFlow en http://localhost:${PORT}`));
